SELECT a.DOMAIN_ID , a.COMPANY_CD , b.COMPANY_NM , a.TASK_ID , a.TASK_TITLE , a.TASK_DETAIL , a.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM005', a.TASK_STATE_CD, a.COMPANY_CD, a.DOMAIN_ID) AS TASK_STATE_NM , a.TASK_DT , a.TASK_OWNER_MEMBER_ID , a.TASK_RECEIVER_MEMBER_ID , SF_GET_MEMBER_NAME(a.TASK_RECEIVER_MEMBER_ID) AS TASK_RECEIVER_MEMBER_NM , a.TASK_REVIEW_CONTENT , a.TASK_REVIEW_DT , a.DEL_YN , a.UPDATE_USR , a.UPDATE_DT , a.CREATE_USR , a.CREATE_DT , c.EMP_NM AS TASK_OWNER_MEMBER_NM , c.EMP_ENG_NM AS TASK_OWNER_MEMBER_ENG_NM , c.COMPANY_CD AS TASK_OWNER_MEMBER_COMPANY_CD
, d.TASK_EMP_CD , SF_GET_CODE_NM('ko-KR', 'CM005', d.TASK_EMP_CD, d.COMPANY_CD, d.DOMAIN_ID) AS TASK_EMP_NM , d.TASK_EMP_REVIEW_DT
FROM REPORT_TASK_MASTER a INNER JOIN COMPANY_MASTER b ON (a.DOMAIN_ID = b.DOMAIN_ID AND a.COMPANY_CD = b.COMPANY_CD) INNER JOIN EMP_MASTER c ON (a.DOMAIN_ID = c.DOMAIN_ID AND a.COMPANY_CD = c.COMPANY_CD AND a.TASK_OWNER_MEMBER_ID = c.EMAIL)
INNER JOIN REPORT_TASK_EMP d ON (a.DOMAIN_ID = d.DOMAIN_ID AND a.TASK_ID = d.TASK_ID)
WHERE a.TASK_ID = #{taskId} AND a.DOMAIN_ID = #{domainId} AND a.DEL_YN = #{delYn}
AND d.EMAIL = #{email}

    	SELECT
			COUNT(*) AS CNT	
    	FROM
    		REPORT_TASK_MASTER a
    	WHERE
    		a.TASK_OWNER_MEMBER_ID = #{taskOwnerMemberId}
    		AND a.DOMAIN_ID = #{domainId}
    		AND a.COMPANY_CD = #{companyCd}		
    		AND a.TASK_STATE_CD = #{taskStateCd}
    		AND a.DEL_YN = #{delYn}


			AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')



			AND a.TASK_DT >= #{fromDt}



			AND a.TASK_DT  <= #{toDt}

SELECT a.DOMAIN_ID , a.COMPANY_CD , b.COMPANY_NM , a.TASK_ID , a.TASK_TITLE , a.TASK_DETAIL , a.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM005', a.TASK_STATE_CD, a.COMPANY_CD, a.DOMAIN_ID) AS TASK_STATE_NM , a.TASK_DT , a.TASK_OWNER_MEMBER_ID , a.TASK_REVIEW_CONTENT , a.TASK_REVIEW_DT , a.DEL_YN , a.UPDATE_USR , a.UPDATE_DT , a.CREATE_USR , a.CREATE_DT , c.EMP_NM AS TASK_OWNER_MEMBER_NM , c.EMP_ENG_NM AS TASK_OWNER_MEMBER_ENG_NM FROM REPORT_TASK_MASTER a INNER JOIN COMPANY_MASTER b ON (a.DOMAIN_ID = b.DOMAIN_ID AND a.COMPANY_CD = b.COMPANY_CD) INNER JOIN EMP_MASTER c ON (a.DOMAIN_ID = c.DOMAIN_ID AND a.COMPANY_CD = c.COMPANY_CD AND a.TASK_OWNER_MEMBER_ID = c.EMAIL) WHERE a.TASK_OWNER_MEMBER_ID = #{taskOwnerMemberId} AND a.DOMAIN_ID = #{domainId} AND a.COMPANY_CD = #{companyCd} AND a.TASK_STATE_CD = #{taskStateCd} AND a.DEL_YN = #{delYn}
AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')
AND a.TASK_DT >= #{fromDt}
AND a.TASK_DT <= #{toDt}
ORDER BY a.TASK_DT DESC

    	SELECT
			COUNT(*) AS CNT	
    	FROM
    		REPORT_TASK_MASTER a
    	WHERE
    		a.TASK_OWNER_MEMBER_ID = #{taskOwnerMemberId}
    		AND a.DOMAIN_ID = #{domainId}
    		AND a.COMPANY_CD = #{companyCd}		
    		AND a.TASK_STATE_CD IN ('CM005CD002', 'CM005CD003')
    		AND a.DEL_YN = #{delYn}


			AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')



			AND a.TASK_STATE_CD = #{taskStateCd}



			AND a.TASK_DT >= #{fromDt}



			AND a.TASK_DT  <= #{toDt}

SELECT a.DOMAIN_ID , a.COMPANY_CD , b.COMPANY_NM , a.TASK_ID , a.TASK_TITLE , a.TASK_DETAIL , a.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM005', a.TASK_STATE_CD, a.COMPANY_CD, a.DOMAIN_ID) AS TASK_STATE_NM , a.TASK_DT , a.TASK_OWNER_MEMBER_ID , a.TASK_REVIEW_CONTENT , a.TASK_REVIEW_DT , a.DEL_YN , a.UPDATE_USR , a.UPDATE_DT , a.CREATE_USR , a.CREATE_DT , c.EMP_NM AS TASK_OWNER_MEMBER_NM , c.EMP_ENG_NM AS TASK_OWNER_MEMBER_ENG_NM FROM REPORT_TASK_MASTER a INNER JOIN COMPANY_MASTER b ON (a.DOMAIN_ID = b.DOMAIN_ID AND a.COMPANY_CD = b.COMPANY_CD) INNER JOIN EMP_MASTER c ON (a.DOMAIN_ID = c.DOMAIN_ID AND a.COMPANY_CD = c.COMPANY_CD AND a.TASK_OWNER_MEMBER_ID = c.EMAIL) WHERE a.TASK_OWNER_MEMBER_ID = #{taskOwnerMemberId} AND a.DOMAIN_ID = #{domainId} AND a.COMPANY_CD = #{companyCd} AND a.TASK_STATE_CD IN ('CM005CD002', 'CM005CD003') AND a.DEL_YN = #{delYn}
AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')
AND a.TASK_STATE_CD = #{taskStateCd}
AND a.TASK_DT >= #{fromDt}
AND a.TASK_DT <= #{toDt}
ORDER BY a.TASK_DT DESC

SELECT COUNT(*) FROM ( SELECT a.DOMAIN_ID , a.COMPANY_CD , a.TASK_ID , c.EMP_NM AS TASK_OWNER_MEMBER_NM FROM REPORT_TASK_MASTER a INNER JOIN EMP_MASTER c ON (a.DOMAIN_ID = c.DOMAIN_ID AND a.COMPANY_CD = c.COMPANY_CD AND a.TASK_OWNER_MEMBER_ID = c.EMAIL) INNER JOIN REPORT_TASK_EMP d ON (a.DOMAIN_ID = d.DOMAIN_ID AND a.TASK_ID = d.TASK_ID) WHERE d.EMAIL = #{taskReceiverMemberId} AND a.DOMAIN_ID = #{domainId} AND a.TASK_STATE_CD IN ('CM005CD002', 'CM005CD003') AND a.DEL_YN = #{delYn}
AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')
AND d.TASK_EMP_CD = #{taskStateCd}
AND a.TASK_DT >= #{fromDt}
AND a.TASK_DT <= #{toDt}
) T
AND T.TASK_OWNER_MEMBER_NM LIKE REPLACE(CONCAT('%', #{taskOnwerMemberNm}, '%'), ' ','')

SELECT T.* FROM ( SELECT a.DOMAIN_ID , a.COMPANY_CD , b.COMPANY_NM , a.TASK_ID , a.TASK_TITLE , a.TASK_DETAIL , a.TASK_STATE_CD , SF_GET_CODE_NM('ko-KR', 'CM005', a.TASK_STATE_CD, a.COMPANY_CD, a.DOMAIN_ID) AS TASK_STATE_NM , a.TASK_DT , a.TASK_OWNER_MEMBER_ID , a.TASK_REVIEW_CONTENT , a.TASK_REVIEW_DT , a.DEL_YN , a.UPDATE_USR , a.UPDATE_DT , a.CREATE_USR , a.CREATE_DT , c.EMP_NM AS TASK_OWNER_MEMBER_NM , c.EMP_ENG_NM AS TASK_OWNER_MEMBER_ENG_NM , e.EMP_NM AS TASK_RECEIVER_MEMBER_NM , e.EMP_ENG_NM AS TASK_RECEIVER_MEMBER_ENG_NM , d.TASK_EMP_CD , SF_GET_CODE_NM('ko-KR', 'CM005', d.TASK_EMP_CD, d.COMPANY_CD, d.DOMAIN_ID) AS TASK_EMP_NM , d.TASK_EMP_REVIEW_DT FROM REPORT_TASK_MASTER a INNER JOIN COMPANY_MASTER b ON (a.DOMAIN_ID = b.DOMAIN_ID AND a.COMPANY_CD = b.COMPANY_CD) INNER JOIN EMP_MASTER c ON (a.DOMAIN_ID = c.DOMAIN_ID AND a.COMPANY_CD = c.COMPANY_CD AND a.TASK_OWNER_MEMBER_ID = c.EMAIL) INNER JOIN REPORT_TASK_EMP d ON (a.DOMAIN_ID = d.DOMAIN_ID AND a.TASK_ID = d.TASK_ID) INNER JOIN EMP_MASTER e ON (d.DOMAIN_ID = e.DOMAIN_ID AND d.COMPANY_CD = e.COMPANY_CD AND d.EMAIL = e.EMAIL) WHERE d.EMAIL = #{taskReceiverMemberId} AND a.DOMAIN_ID = #{domainId} AND a.TASK_STATE_CD IN ('CM005CD002', 'CM005CD003') AND a.DEL_YN = #{delYn}
AND a.TASK_TITLE LIKE REPLACE(CONCAT('%', #{taskTitle}, '%'), ' ','')
AND d.TASK_EMP_CD = #{taskStateCd}
AND a.TASK_DT >= #{fromDt}
AND a.TASK_DT <= #{toDt}
ORDER BY a.TASK_DT DESC
) T
AND T.TASK_OWNER_MEMBER_NM LIKE REPLACE(CONCAT('%', #{taskOnwerMemberNm}, '%'), ' ','')

mapper.insert:
INSERT REPORT_TASK_MASTER (
	DOMAIN_ID
	, COMPANY_CD
	, TASK_ID
	, TASK_TITLE
	, TASK_DETAIL
	, TASK_STATE_CD
	, TASK_DT
	, TASK_OWNER_MEMBER_ID
	, TASK_REVIEW_CONTENT
	, DEL_YN
	, UPDATE_USR
	, UPDATE_DT
	, CREATE_USR
	, CREATE_DT
)
VALUES (
	#{domainId}
	, #{companyCd}
	, #{taskId}
	, #{taskTitle}
	, #{taskDetail}
	, #{taskStateCd}
	, #{taskDt}
	, #{taskOwnerMemberId}
	, #{taskReviewContent}
	, #{delYn}
	, #{updateUsr}
	, NOW()
	, #{createUsr}
	, NOW()
)

INSERT
	REPORT_TASK_EMP (
		DOMAIN_ID
		, COMPANY_CD
		, EMAIL
		, TASK_ID
		, TASK_EMP_CD
		, UPDATE_USR
		, UPDATE_DT
		, CREATE_USR
		, CREATE_DT
	)
	VALUES (
		#{domainId}
		, #{companyCd}
		, #{email}
		, #{taskId}
		, #{taskEmpCd}
		, #{createUsr}
		, NOW()
		, #{createUsr}
		, NOW()
	)

mapper.update:
		UPDATE REPORT_TASK_MASTER

			TASK_TITLE 					= #{taskTitle}
			, TASK_DETAIL 				= #{taskDetail}
			, TASK_DT 					= #{taskDt}
			, TASK_OWNER_MEMBER_ID 		= #{taskOwnerMemberId}
 			, TASK_RECEIVER_MEMBER_ID 	= #{taskReceiverMemberId}


			, TASK_REVIEW_CONTENT 		= #{taskReviewContent}


			, UPDATE_USR 				= #{updateUsr}
			, UPDATE_DT 				= NOW()


			TASK_ID = #{taskId}

UPDATE REPORT_TASK_MASTER

	TASK_STATE_CD	= #{taskStateCd}



		, TASK_REVIEW_DT = #{taskReviewDt}


		, TASK_REVIEW_DT = DATE_FORMAT(NOW(), '%Y%m%d')



	, UPDATE_USR 	= #{updateUsr}
	, UPDATE_DT 	= NOW()


	TASK_ID = #{taskId}

UPDATE REPORT_TASK_EMP

	TASK_EMP_CD = "CM005CD003"


		, TASK_EMP_REVIEW_DT = #{taskReviewDt}


		, TASK_EMP_REVIEW_DT = DATE_FORMAT(NOW(), '%Y%m%d')


	, UPDATE_USR 	= #{updateUsr}
	, UPDATE_DT 	= NOW()


	TASK_ID = #{taskId}
	AND EMAIL = #{updateUsr}

UPDATE REPORT_TASK_MASTER

	DEL_YN 			= 'Y'
	, UPDATE_USR 	= #{updateUsr}
	, UPDATE_DT 	= NOW()


	TASK_ID = #{taskId}
